CREATE SCHEMA IF NOT EXISTS "public";
CREATE TYPE "UserRole" AS ENUM ('ADMIN', 'OPERATOR', 'VIEWER');
CREATE TYPE "ContactStatus" AS ENUM ('ACTIVE', 'INACTIVE', 'BLOCKED');
CREATE TYPE "CampaignType" AS ENUM ('REMINDER', 'NOTICE', 'INFORMATIONAL', 'PROMOTION', 'URGENT');
CREATE TYPE "CampaignChannel" AS ENUM ('WHATSAPP', 'SMS', 'BOTH');
CREATE TYPE "ExecutionMode" AS ENUM ('DEMO', 'TWILIO_TEST', 'LIVE');
CREATE TYPE "CampaignStatus" AS ENUM ('DRAFT', 'SCHEDULED', 'PROCESSING', 'COMPLETED', 'CANCELLED', 'FAILED');
CREATE TYPE "RecipientStatus" AS ENUM ('PENDING', 'QUEUED', 'SENT', 'DELIVERED', 'READ', 'FAILED', 'CANCELLED', 'SIMULATED');
CREATE TABLE "User" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "email" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "role" "UserRole" NOT NULL DEFAULT 'VIEWER', "isActive" BOOLEAN NOT NULL DEFAULT true, "lastLoginAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Contact" ("id" TEXT NOT NULL, "firstName" TEXT NOT NULL, "lastName" TEXT NOT NULL, "documentId" TEXT, "phone" TEXT NOT NULL, "email" TEXT, "departmentOrZone" TEXT, "groupName" TEXT, "status" "ContactStatus" NOT NULL DEFAULT 'ACTIVE', "whatsappOptIn" BOOLEAN NOT NULL DEFAULT false, "smsOptIn" BOOLEAN NOT NULL DEFAULT false, "consentSource" TEXT, "consentAt" TIMESTAMP(3), "optOutAt" TIMESTAMP(3), "isTwilioTestNumber" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Contact_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Segment" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "description" TEXT, "filters" JSONB NOT NULL, "isDynamic" BOOLEAN NOT NULL DEFAULT true, "createdById" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Segment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Campaign" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "type" "CampaignType" NOT NULL, "channel" "CampaignChannel" NOT NULL, "executionMode" "ExecutionMode" NOT NULL DEFAULT 'DEMO', "status" "CampaignStatus" NOT NULL DEFAULT 'DRAFT', "message" TEXT NOT NULL, "whatsappTemplate" TEXT, "variables" JSONB, "scheduledAt" TIMESTAMP(3), "sentAt" TIMESTAMP(3), "segmentId" TEXT, "createdById" TEXT NOT NULL, "estimatedRecipients" INTEGER NOT NULL DEFAULT 0, "estimatedCost" DECIMAL(12,4) NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Campaign_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CampaignRecipient" ("id" TEXT NOT NULL, "campaignId" TEXT NOT NULL, "contactId" TEXT NOT NULL, "channel" "CampaignChannel" NOT NULL, "status" "RecipientStatus" NOT NULL DEFAULT 'PENDING', "providerMessageId" TEXT, "errorMessage" TEXT, "renderedMessage" TEXT NOT NULL, "estimatedCost" DECIMAL(12,4) NOT NULL DEFAULT 0, "sentAt" TIMESTAMP(3), "deliveredAt" TIMESTAMP(3), "readAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "CampaignRecipient_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AuditLog" ("id" TEXT NOT NULL, "userId" TEXT, "action" TEXT NOT NULL, "entity" TEXT NOT NULL, "entityId" TEXT NOT NULL, "metadata" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AuditLog_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AppSetting" ("id" TEXT NOT NULL, "organizationName" TEXT NOT NULL, "supportEmail" TEXT, "supportPhone" TEXT, "allowedStartHour" INTEGER NOT NULL DEFAULT 8, "allowedEndHour" INTEGER NOT NULL DEFAULT 20, "whatsappUtilityRatePerThousand" DECIMAL(12,4) NOT NULL DEFAULT 0, "whatsappMarketingRatePerThousand" DECIMAL(12,4) NOT NULL DEFAULT 0, "smsRatePerThousand" DECIMAL(12,4) NOT NULL DEFAULT 0, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "AppSetting_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE UNIQUE INDEX "Contact_phone_key" ON "Contact"("phone");
CREATE UNIQUE INDEX "CampaignRecipient_campaignId_contactId_channel_key" ON "CampaignRecipient"("campaignId", "contactId", "channel");
ALTER TABLE "Segment" ADD CONSTRAINT "Segment_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Campaign" ADD CONSTRAINT "Campaign_segmentId_fkey" FOREIGN KEY ("segmentId") REFERENCES "Segment"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Campaign" ADD CONSTRAINT "Campaign_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "CampaignRecipient" ADD CONSTRAINT "CampaignRecipient_campaignId_fkey" FOREIGN KEY ("campaignId") REFERENCES "Campaign"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "CampaignRecipient" ADD CONSTRAINT "CampaignRecipient_contactId_fkey" FOREIGN KEY ("contactId") REFERENCES "Contact"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "AuditLog" ADD CONSTRAINT "AuditLog_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
